        require(capacity >= 1) { "Capacity must be at least 1, got $capacity" }
    }

    private class Node<K, V>(var key: K, var value: V) {
        var prev: Node<K, V>? = null
        var next: Node<K, V>? = null
    }

    private val head: Node<K, V> = Node<K, V>(null as K?, null as V?)
    private val tail: Node<K, V> = Node<K, V>(null as K?, null as V?)
    private val map: MutableMap<K, Node<K, V>> = HashMap()
    private var size: Int = 0

    init {
        head.next = tail
        tail.prev = head
    }

    val size: Int
        get() = this.size

    operator fun get(key: K): V? {
        val node = map[key] ?: return null
        // Move to end (most recently used)
        detach(node)
        attach(node)
        return node.value
    }

    operator fun set(key: K, value: V) {
        val existingNode = map[key]
        if (existingNode != null) {
            // Update existing node
            existingNode.value = value
            // Move to end (most recently used)
            detach(existingNode)
            attach(existingNode)
        } else {
            // Create new node
            val newNode = Node(key, value)
            map[key] = newNode
            attach(newNode)
            size++

            // Evict if needed
            if (size > capacity) {
                val lruNode = head.next ?: throw IllegalStateException("LRU cache is empty but size > capacity")
                detach(lruNode)
                map.remove(lruNode.key)
                onEvict(lruNode.key, lruNode.value)
                size--
            }
        }
    }

    fun remove(key: K): V? {
        val node = map.remove(key) ?: return null
        detach(node)
        size--
        return node.value
    }

    fun keys(): List<K> {
        val result = mutableListOf<K>()
        var current = head.next
        while (current != tail) {
            current?.let { result.add(it.key) }
            current = current?.next
        }
        return result
    }

    operator fun contains(key: K): Boolean = map.containsKey(key)

    private fun detach(node: Node<K, V>) {
        node.prev?.next = node.next
        node.next?.prev = node.prev
        node.prev = null
        node.next = null
    }

    private fun attach(node: Node<K, V>) {
        node.prev = tail.prev
        node.next = tail
        tail.prev?.next = node
        tail.prev = node
    }
}
